import{_ as a,a as t,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 8 A famous monastery","description":"学习 地点介词与移动路径，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 8 A famous monastery","description":"学习 地点介词与移动路径，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 地点介词与移动路径，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 7 Mutilated ladies","link":"/life/english/new-concept/book-3/unit-01/lesson-007"},"next":{"text":"第三册：培养技能 · Lesson 9 Flying cats","link":"/life/english/new-concept/book-3/unit-01/lesson-009"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 7 Mutilated ladies","link":"/life/english/new-concept/book-3/unit-01/lesson-007"},"next":{"text":"第三册：培养技能 · Lesson 9 Flying cats","link":"/life/english/new-concept/book-3/unit-01/lesson-009"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-008.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-008.md"}'),l={name:"life/english/new-concept/book-3/unit-01/lesson-008.md"};function i(s,e,r,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-8-a-famous-monastery" tabindex="-1">第三册：培养技能 · Lesson 8 A famous monastery <a class="header-anchor" href="#第三册-培养技能-·-lesson-8-a-famous-monastery" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 8 A famous monastery&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从偏远建筑的地理位置和到访条件出发，练习用介词短语提供空间线索。介绍景点时应帮助读者建立路线，而不是堆积漂亮形容词。目标是准确说明建筑在哪里、旅客从哪里经过以及何时可以抵达，并区分地点关系和移动方向。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>remote</td><td>/rɪˈməʊt/</td><td>adj.</td><td>偏远的</td><td>a remote village</td></tr><tr><td>path</td><td>/pɑːθ/</td><td>n.</td><td>小路</td><td>a mountain path</td></tr><tr><td>cliff</td><td>/klɪf/</td><td>n.</td><td>悬崖</td><td>a steep cliff</td></tr><tr><td>shelter</td><td>/ˈʃeltə/</td><td>n.</td><td>避难处</td><td>find shelter</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>on foot — 步行，通常不用 by foot</li><li>at the foot of — 在山或建筑物底部</li></ul><h2 id="语法讲解-地点介词与移动路径" tabindex="-1">语法讲解：地点介词与移动路径 <a class="header-anchor" href="#语法讲解-地点介词与移动路径" aria-label="Permalink to &quot;语法讲解：地点介词与移动路径&quot;">​</a></h2><p>at 常把地点看作活动点，in 强调空间内部或较大区域，on 常表示接触表面；这些只是基本倾向，实际搭配还需考虑名词和语境。across 表示从一边到另一边，through 强调穿过内部，along 表示沿着路线。描述高度可用 above，描述紧邻上方并覆盖有时用 over，但二者并不总能互换。地点短语可以放句首建立场景，谓语仍须与真正的主语保持一致，不能被介词后的复数名词干扰。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>A narrow path runs through the forest and ends at the old gate.</p></blockquote><p>一条狭窄小路穿过森林，终止于古老的大门。</p><p>through 描述穿过内部空间，at 把大门作为终点；runs 与 ends 共用单数主语 path。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>across the forest 强调横穿整个林区，through the forest 强调在林中穿行；路线视角不同，不宜机械判为同义。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读时突出 above、through、at，在纸上同步画出湖、树林和门，核对介词是否真正传达了空间关系。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The library stands above a small lake. A stone path leads through the pine trees. Visitors leave their cars at the lower gate and walk uphill.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句为第一次来访的人描述山中图书馆的位置和路线。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>三个地点短语依次建立位置、路径和起点，读者可以据此形成路线图。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：We walked ___ the bridge from one bank to the other.（across/inside）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> across</p><p><strong>解析：</strong> 明确从桥一端到另一端。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句的主语是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> A narrow path</p><p><strong>解析：</strong> 不是 forest，也不是 gate。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>翻译：我们步行到达。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We arrived on foot.</p><p><strong>解析：</strong> 步行的常用搭配是 on foot。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：地点介词与移动路径。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-007">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-009">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(l,[["render",i]]);export{u as __pageData,f as default};
